INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','authority_reference',1,'harness/archive/task-control-v1/chains/develop-architecture-decision-skill.chain.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','authority_reference',2,'harness/archive/task-control-v1/tasks/ARCHITECTURE-DECISION-SKILL-1.md');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','authorized_scope',0,'It creates and activates the read-only `develop-architecture-decision` skill, canonical/reference/descriptor resources, byte-identical live resources, controlled H6-only fixtures and validator, generic/local manifest and profile synchronization, eight-skill inventory/validation, current local replay, selected local route, maintained harness documentation, and task evidence.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','completion_criterion',0,'Run ownership preflight with the task-specific chain:');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','completion_criterion',1,'```text
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','completion_criterion',2,'Then run task completion, current H3 resource validation, eight-skill capability validation, selected local route, controlled architecture cases, JSON/link checks, and diff/protected-nonmutation checks. Reviewer gate is required after deterministic completion. One consolidated correction pass is permitted after that review. Final output is one pending skill-acceptance checkpoint; acceptance must not invoke the skill, initialize H6, or activate a successor.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','exclusion',0,'The current human instruction authorizes this bounded one-writer harness resource task. It creates and activates the read-only `develop-architecture-decision` skill, canonical/reference/descriptor resources, byte-identical live resources, controlled H6-only fixtures and validator, generic/local manifest and profile synchronization, eight-skill inventory/validation, current local replay, selected local route, maintained harness documentation, and task evidence.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','exclusion',1,'Historical implementation and review assignments are retained only in Git; current work routes through durable harness roles.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','exclusion',2,'No `.pi/agents/`, real H6 work, dispatch, ownership semantics, P2/P3/H5 surfaces, production/project tests or schemas, dependencies, locks, SQLite, replay redesign, execution/release, historical catalogs, final checkpoint, commit, or push may be changed. Canonical generic resources remain authoritative; local depends on generic and live resources are synchronized from canonical. The selected route remains `local`.');
