INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('B','authorized_scope',5,'structured partial, interrupted, resumed, missing, and checksum-mismatch states.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('B','completion_criterion',0,'Implementation, software-verification tests, documentation, independent read-only review, parent verification, and human acceptance are all required. Acceptance contributes to G01a and unlocks C, E, F, and H according to their remaining prerequisites; it launches none.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('B','exclusion',0,'No `logical_path_or_uri` field is permitted. Storage technology, deletion, unrestricted environment capture, production manifests, and real execution are excluded.');
