INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d','authorized_scope',0,'Plan null and planted-defect cases whose exact impurity operator and comparison map are known.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d','authorized_scope',1,'Separate supercell folding, basis or gauge alignment, scalar energy-reference alignment, finite-size effects, model-class residuals, and bound-state observables.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d','authorized_scope',2,'Exercise local and controlled nonlocal impurity classes without interpreting them as silicon dopants.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d','completion_criterion',0,'The null case returns the declared zero extraction after alignment and the planted case recovers the known defect within explicit numerical error.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d','completion_criterion',1,'Alignment, finite-size, reduction, optimization, spectral, wavefunction, and operator errors remain distinct.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d','completion_criterion',2,'Synthetic exercise provenance and limitations are retained without a material-specific or scientific-validation claim.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d','exclusion',0,'No pristine or doped silicon calculation, impurity interpretation, external execution, or public scientific API stabilization is authorized.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d','exclusion',1,'Equal dimensions or labels alone do not establish alignment.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d','exclusion',2,'A correct bound-state energy does not establish recovery or transferability of the planted operator.');
