INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','authority_reference',1,'calculations/research-monograph/impurity-defect-1d/result.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','authority_reference',2,'docs/publications/research-monograph/appendices/I-impurity-effective-mass-models.tex');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','authorized_scope',0,'Plan rank-one and, when bounded and useful, low-rank Hermitian defects on the accepted scalar or two-orbital one-dimensional represented parent.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','authorized_scope',1,'Derive bound-state conditions from an independently evaluated resolvent, determinant, or equivalent finite-rank identity without reproducing the eigensolver under test.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','authorized_scope',2,'Compare analytical energies, bound-state counts, projectors or isolated-state fidelities, and extracted operators under declared finite-size and representation conventions.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','completion_criterion',0,'At least one nontrivial finite-rank defect has an explicit analytical or independently evaluated spectral condition with a declared domain and root-selection rule.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','completion_criterion',1,'Numerical bound-state energies and equal-rank subspaces agree with the oracle within frozen tolerances over a bounded parameter and supercell sequence.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','completion_criterion',2,'Threshold, degeneracy, unequal-rank, and no-bound-state cases retain explicit outcomes, provenance, and limitations.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','exclusion',0,'A numerical diagonalization duplicated in different syntax is not an analytical oracle.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','exclusion',1,'Agreement with the finite-rank oracle does not establish a continuum limit, material impurity model, scientific validation, or uncertainty quantification.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.analytical-oracle','exclusion',2,'No material calculation, external execution, dependency change, or public API freeze is authorized.');
