INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.blind-alignment','authorized_scope',0,'Plan uniquely identifiable, gauge-equivalent, degenerate, noisy, and incompatible synthetic alignment cases derived from the accepted defect-1D represented spaces.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.blind-alignment','authorized_scope',1,'Declare the overlap, site-anchor, orbital-label, spin-frame, and energy-reference information available to the alignment procedure before evaluation.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.blind-alignment','authorized_scope',2,'Separate alignment-map error, extraction error, model-class residual, spectral error, and wavefunction error, with principal-angle and conditioning diagnostics retained explicitly.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.blind-alignment','completion_criterion',0,'Recover identifiable hidden maps up to the declared gauge or symmetry equivalence and recover the planted impurity operator within independently established numerical error.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.blind-alignment','completion_criterion',1,'Report non-identifiability, degeneracy, poor conditioning, incompatible rank, incompatible spin space, and incompatible retained subspaces through structured stopping outcomes rather than forced fits.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.blind-alignment','completion_criterion',2,'Retain deterministic synthetic inputs, an independent verifier, figures, provenance, and limitations without a material or scientific-validation claim.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.blind-alignment','exclusion',0,'No silicon, dopant, DFT, production Wannier, external execution, scientific validation, uncertainty quantification, or public API stabilization is authorized.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.blind-alignment','exclusion',1,'The hidden oracle map must not be supplied to the inference action except for post hoc verification.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.blind-alignment','exclusion',2,'Map recovery in one synthetic representation does not establish uniqueness or transferability for material calculations.');
