INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','authority_reference',3,'docs/publications/research-monograph/references.bib');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','authorized_scope',0,'Plan frozen fixed-peak and fixed-integrated defect families with independently varied lattice scale, continuum discretization, domain length, supercell size, and profile width.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','authorized_scope',1,'Track operator or compressed-operator residuals, bound-state counts, binding energies, equal-rank subspace fidelities, high-momentum weight, exterior residuals, and cross couplings separately.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','authorized_scope',2,'Test a declared crossover criterion only after discretization, finite-domain, periodic-image, and profile-smoothness effects have been separated.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','authorized_scope',3,'In the retained report, map continuum-mesh refinement, lattice-scale or band-edge scaling, finite-volume refinement, and defect-profile scaling to their applicable primary literature without treating those distinct limits as interchangeable.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','completion_criterion',0,'Each claimed limiting trend is supported by at least one refinement axis that does not simultaneously change the physical profile or normalization convention.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','completion_criterion',1,'Any proposed continuum crossover passes frozen exterior, cross-coupling, spectral, and wavefunction criteria and remains stable under the declared refinement sequence; otherwise no crossover is reported over the tested domain.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','completion_criterion',2,'Deterministic inputs, independent verification, provenance, numerical limitations, and the absence of material validation or UQ are retained.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','completion_criterion',3,'The retained report distinguishes the tested refinement path from the hypotheses and conclusions of discrete-to-continuum, band-edge homogenization, finite-volume, and semiconductor effective-mass references.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','exclusion',0,'Increasing profile width on one fixed grid is not sufficient to establish a continuum limit.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','exclusion',1,'Fixed-peak and fixed-integrated families must not be combined into one convergence sequence.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.continuum-refinement','exclusion',2,'No silicon, dopant, DFT, production Wannier, external execution, scientific validation, uncertainty quantification, or public API freeze is authorized.');
