INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','authority_reference',1,'calculations/research-monograph/impurity-defect-1d/result.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','authority_reference',2,'docs/publications/research-monograph/appendices/I-impurity-effective-mass-models.tex');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','authorized_scope',0,'Plan an independently implemented momentum-space extraction route using the same frozen synthetic parent, supercell, planted defects, and represented-space conventions as the accepted baseline.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','authorized_scope',1,'Compare real-space extraction followed by transformation with transformation followed by fiberwise extraction, after applying the same declared alignment and energy-reference maps.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','authorized_scope',2,'Retain representation, alignment, quadrature or mesh, truncation, route, spectral, and wavefunction discrepancies as separate diagnostics.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','completion_criterion',0,'The two independently implemented routes agree within a frozen numerical tolerance for null, local, nonlocal, collinear, and spin-mixing controls when their mathematical operations commute.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','completion_criterion',1,'Deliberately changed fitting domains, weights, truncations, or unmatched maps produce explicit noncommutativity or stopping results rather than nominal agreement.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','completion_criterion',2,'Implementation independence, deterministic inputs, independent verification, provenance, and bounded limitations are documented.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','exclusion',0,'No route may establish independence merely by importing the other route''s extraction implementation.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','exclusion',1,'Route agreement does not establish material validity, continuum validity, scientific validation, or transferability.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.independent-route','exclusion',2,'No material calculation, external execution, dependency change, or public API freeze is authorized.');
