INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','authority_reference',3,'docs/publications/research-monograph/references.bib');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','authorized_scope',0,'Identify and verify primary sources for retained-space alignment, Wannier or localized-basis Hamiltonian differences, impurity operators, finite-rank spectral methods, supercell image effects, and envelope or effective-mass limits.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','authorized_scope',1,'Compare the benchmark''s definitions, controls, failure modes, and evidence boundary with the verified literature, distinguishing established methods from the contribution of the integrated reproducible exercise.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','authorized_scope',2,'Update Appendix I and its bibliography with claim-level attribution, unresolved citation notes, and a conservative novelty statement.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','authorized_scope',3,'Begin from, but do not limit the search to, Koster--Slater finite-rank impurity methods; Simon and Parzygnat--Lee--Avniel--Johnson weak-binding or localization results; Hoefer--Weinstein and Duchene--Vukicevic--Weinstein band-edge homogenization; Nakamura--Tadano discrete-to-continuum convergence; Koenig--Lee--Hammer finite-volume bound-state analysis; and Kohn--Luttinger and Gamble et al. semiconductor effective-mass, central-cell, and multivalley boundaries.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','authorized_scope',4,'Distinguish continuum numerical-grid refinement, physical lattice-scale refinement, weak slowly varying band-edge scaling, finite-volume refinement, and changes of defect profile or normalization; determine source applicability separately for each limit.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','completion_criterion',0,'Every substantive positioning claim is supported by an identified and checked primary source or remains explicitly marked unresolved.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','completion_criterion',1,'The resulting prose distinguishes methodological integration and reproducibility from new physics, a new alignment theorem, material validation, or a new localization algorithm.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','completion_criterion',2,'Bibliographic metadata, quotations if any, and the final claim boundary are independently checked and the manuscript builds without warnings.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','completion_criterion',3,'A claim-to-source matrix records, for every cited methodological precedent, the operator class, dimension, scaling parameter, state-space identification, spectral regime, defect assumptions, finite-volume assumptions, conclusion, and mismatch with the project''s represented benchmark.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','completion_criterion',4,'The final positioning states that established component methods do not by themselves establish this benchmark''s continuum crossover, material validity, or novelty; any contribution claim is limited to what remains after the full primary-source comparison.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','exclusion',0,'Bibliography presence alone does not establish that a source supports a claim.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','exclusion',1,'No novelty, priority, material transferability, scientific validation, publication acceptance, or release claim may be inferred from the synthetic exercises.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('research-monograph.exercises.impurity.defect-1d.literature-positioning','exclusion',2,'No material calculation, external scientific execution, dependency change, publication submission, or release action is authorized.');
